import {build} from 'esbuild';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
mkdirSync('lib',{recursive:true});
const source=readFileSync('vendor/client.pdf.js','utf8'), provenance=JSON.parse(readFileSync('vendor/source.json','utf8'));
if(hash(source)!==provenance.sha256)throw new Error('PDF 引擎快照发生变化，请重新审核');
let engine=source.replace('id: "@deepseek-ai/dsh-client-ui-sidebar-documentpreview"','id: "dsh-pdf-bookmarks"').replace('chunk: "client.pdf.js"','chunk: "client.engine.js"');
if(engine===source)throw new Error('PDF 模块结构变化');
engine=engine.replace('exports.PdfBody = PdfBody;', 'exports.openPdf = openPdf; exports.renderPdfPage = renderPdfPage; exports.pdfTextRenderer = pdfTextRenderer; exports.textClass = PdfBody_module_css_default.text;');
engine=engine.replaceAll('data-plugin = "@deepseek-ai/dsh-client-ui-sidebar-documentpreview"','data-plugin = "dsh-pdf-bookmarks"').replace('const tagId = "@deepseek-ai/dsh-client-ui-sidebar-documentpreview/PdfBody.module.css"','const tagId = "dsh-pdf-bookmarks/PdfBody.module.css"').replace('tag.dataset.plugin = "@deepseek-ai/dsh-client-ui-sidebar-documentpreview"','tag.dataset.plugin = "dsh-pdf-bookmarks"');
engine=engine.replace(/\n\/\/# sourceMappingURL=client\.pdf\.js\.map\s*$/,'');
writeFileSync('lib/client.engine.js',engine);
const compiled=await build({entryPoints:['src/client.js'],bundle:true,write:false,format:'cjs',platform:'browser',target:'chrome130',external:['react'],loader:{'.css':'text'},minify:false});
const body=compiled.outputFiles[0].text;
const entry=`// dsh-pdf-bookmarks: small, exception-isolated entry; PDF engine loads only when used.\ntry { window.__ModuleLoader__?.load({id:'dsh-pdf-bookmarks',factory:(require)=>{try {const module={exports:{}};const exports=module.exports;\n${body}\nconst plugin=module.exports;return {inject:plugin.inject,apply:ctx=>plugin.apply(ctx,()=>require.async('./client.engine.js'))};} catch(error){console.warn('[dsh-pdf-bookmarks] client disabled',error);return {apply(){}};}}}); } catch(error) { console.warn('[dsh-pdf-bookmarks] module registration skipped',error); }\n`;
writeFileSync('lib/client.js',entry);
const files=Object.fromEntries(['client.js','client.engine.js'].map(name=>[name,hash(readFileSync('lib/'+name))]));
writeFileSync('lib/integrity.json',JSON.stringify({supportedVersions:['0.2.1-rc.2'],files},null,2)+'\n');
console.log('Built exception-isolated entry and offline PDF engine:',files);
